import unittest

from mb_cmn import retired_kq_special_templates as rkqst
from mb_cmn import retired_template_names as rtmpln


class KqSpecialTemplateNormalizationTests(unittest.TestCase):
    def test_old_name_maps_to_expected_canonical_type(self):
        kq_type = rkqst.canonical_special_kq_type_from_name_and_sug(rtmpln.K1Q2_SR_KQQ)

        self.assertEqual(kq_type, "k1q2-sr-kqq")

    def test_unified_name_and_sug_map_to_same_canonical_type(self):
        kq_type = rkqst.canonical_special_kq_type_from_name_and_sug(
            rkqst.UNIFIED_SPECIAL_KQ_TEMPLATE_NAME,
            "כו״ק כתיב מילה חדה וקרי תרתין מילין",
        )

        self.assertEqual(kq_type, "k1q2-sr-kqq")

    def test_unified_name_without_sug_fails_fast(self):
        with self.assertRaises(AssertionError):
            rkqst.canonical_special_kq_type_from_name_and_sug(
                rkqst.UNIFIED_SPECIAL_KQ_TEMPLATE_NAME,
            )

    def test_unified_name_with_unknown_sug_fails_fast(self):
        with self.assertRaises(AssertionError):
            rkqst.canonical_special_kq_type_from_name_and_sug(
                rkqst.UNIFIED_SPECIAL_KQ_TEMPLATE_NAME,
                "סוג שלא מוכר",
            )


if __name__ == "__main__":
    unittest.main()
